import mlx.core as mx
import mlx.core.fast as mf

# Variant A: two-kernel, no atomics
part_k = mf.metal_kernel(
    name="rowsum_partials",
    input_names=["inp"],
    output_names=["partial"],
    source="""
        uint t = thread_position_in_grid.x;
        uint row = t / CHUNKS;
        uint chunk = t % CHUNKS;
        uint start = chunk * THREADS;
        uint end = min(start + THREADS, N);
        float acc = 0.0;
        for (uint j = start; j < end; ++j) {
            acc += inp[row * N + j];
        }
        partial[t] = acc;
    """,
)
fin_k = mf.metal_kernel(
    name="rowsum_finish",
    input_names=["partial"],
    output_names=["out"],
    source="""
        uint row = thread_position_in_grid.x;
        float acc = 0.0;
        for (uint c = 0; c < CHUNKS; ++c) {
            acc += partial[row * CHUNKS + c];
        }
        out[row] = acc;
    """,
)

def row_sum_a(x):
    M, N = x.shape
    threads = 256
    chunks = max(1, (N + threads - 1) // threads)
    grid = M * chunks
    partial = part_k(
        inputs=[x],
        template=[("CHUNKS", chunks), ("THREADS", threads), ("N", N)],
        grid=(grid, 1, 1),
        threadgroup=(min(1024, grid), 1, 1),
        output_shapes=[(grid,)],
        output_dtypes=[mx.float32],
    )[0]
    out = fin_k(
        inputs=[partial],
        template=[("CHUNKS", chunks)],
        grid=(M, 1, 1),
        threadgroup=(1, 1, 1),
        output_shapes=[(M,)],
        output_dtypes=[mx.float32],
    )[0]
    return out

mx.random.seed(0)
x = mx.random.normal((16, 256)).astype(mx.float32)
got = row_sum_a(x)
exp = mx.sum(x, axis=1)
print("Variant A (16,256):", mx.allclose(got, exp, atol=1e-4), mx.max(mx.abs(got-exp)).item())
for shape in [(64,1), (2,4097), (7,33), (3,1000), (4,8)]:
    x = mx.random.normal(shape).astype(mx.float32)
    got = row_sum_a(x); exp = mx.sum(x, axis=1)
    mx.eval(got, exp)
    err = mx.max(mx.abs(got - exp)).item()
    scale = mx.max(mx.abs(exp)).item() + 1e-6
    print(f"  {shape}: err/scale={err/scale:.2e}")
