import time
import mlx.core as mx
import mlx.core.fast as mf

part_k = mf.metal_kernel(
    name="rowsum_partials",
    input_names=["inp"],
    output_names=["partial"],
    source="""
        uint t = thread_position_in_grid.x;
        uint row = t / CHUNKS;
        uint chunk = t % CHUNKS;
        uint start = chunk * THREADS;
        uint end = min(start + THREADS, (uint)N);
        float acc = 0.0;
        for (uint j = start; j < end; ++j) {
            acc += inp[row * N + j];
        }
        partial[t] = acc;
    """,
)
fin_k = mf.metal_kernel(
    name="rowsum_finish",
    input_names=["partial"],
    output_names=["out"],
    source="""
        uint row = thread_position_in_grid.x;
        float acc = 0.0;
        for (uint c = 0; c < CHUNKS; ++c) {
            acc += partial[row * CHUNKS + c];
        }
        out[row] = acc;
    """,
)

def row_sum_a(x):
    M, N = x.shape
    threads = 256
    chunks = max(1, (N + threads - 1) // threads)
    grid = M * chunks
    partial = part_k(
        inputs=[x],
        template=[("CHUNKS", chunks), ("THREADS", threads), ("N", N)],
        grid=(grid, 1, 1),
        threadgroup=(min(1024, grid), 1, 1),
        output_shapes=[(grid,)],
        output_dtypes=[mx.float32],
    )[0]
    out = fin_k(
        inputs=[partial],
        template=[("CHUNKS", chunks)],
        grid=(M, 1, 1),
        threadgroup=(1, 1, 1),
        output_shapes=[(M,)],
        output_dtypes=[mx.float32],
    )[0]
    return out

# threadgroup shared-memory variant (one threadgroup per row)
tg_k = mf.metal_kernel(
    name="rowsum_tg",
    input_names=["inp"],
    output_names=["out"],
    source="""
        uint row = threadgroup_position_in_grid.x;
        uint tid = thread_position_in_threadgroup.x;
        uint nthreads = threads_per_threadgroup.x;
        float acc = 0.0;
        for (uint j = tid; j < N; j += nthreads) {
            acc += inp[row * N + j];
        }
        threadgroup float smem[1024];
        smem[tid] = acc;
        threadgroup_barrier(mem_flags::mem_threadgroup);
        // tree reduction
        for (uint s = nthreads / 2; s > 0; s >>= 1) {
            if (tid < s) {
                smem[tid] += smem[tid + s];
            }
            threadgroup_barrier(mem_flags::mem_threadgroup);
        }
        if (tid == 0) {
            out[row] = smem[0];
        }
    """,
)

def row_sum_c(x, tg=256):
    M, N = x.shape
    out = tg_k(
        inputs=[x],
        template=[("N", N)],
        grid=(M, 1, 1),
        threadgroup=(tg, 1, 1),
        output_shapes=[(M,)],
        output_dtypes=[mx.float32],
    )[0]
    return out

# correctness of C
for shape in [(4, 8), (16, 256), (3, 1000), (7, 33), (64, 1), (2, 4097)]:
    mx.random.seed(0)
    x = mx.random.normal(shape).astype(mx.float32)
    mx.eval(x)
    got = row_sum_c(x)
    exp = mx.sum(x, axis=1)
    mx.eval(got, exp)
    err = mx.max(mx.abs(got - exp)).item()
    scale = mx.max(mx.abs(exp)).item() + 1e-6
    print(f"C {shape}: err/scale={err/scale:.2e}")
x = mx.zeros((16, 300), dtype=mx.float32)
got = row_sum_c(x); mx.eval(got)
print("C zeros max:", mx.max(mx.abs(got)).item())

# benchmark
mx.random.seed(0)
big = mx.random.normal((2048, 8192)).astype(mx.float32)
mx.eval(big)
for name, fn in [("A two-kernel", row_sum_a), ("C threadgroup", lambda z: row_sum_c(z, 512))]:
    fn(big); mx.eval(big)  # warm
    t0 = time.perf_counter()
    for _ in range(20):
        o = fn(big)
    mx.eval(o)
    t1 = time.perf_counter()
    print(f"{name}: {(t1-t0)/20*1000:.2f} ms")

# also compare to builtin sum for reference
mx.eval(mx.sum(big, axis=1))
t0 = time.perf_counter()
for _ in range(20):
    o = mx.sum(big, axis=1)
mx.eval(o)
print(f"builtin mx.sum: {(time.perf_counter()-t0)/20*1000:.2f} ms")
