tg_k = mf.metal_kernel(
    name="rowsum_tg",
    input_names=["inp"],
    output_names=["out"],
    source="""
        uint row = threadgroup_position_in_grid.x;
        uint tid = thread_position_in_threadgroup.x;
        uint nthreads = threads_per_threadgroup.x;
        float acc = 0.0;
        for (uint j = tid; j < N; j += nthreads) {
            acc += inp[row * N + j];
        }
        threadgroup float smem[512];
        smem[tid] = acc;
        threadgroup_barrier(mem_flags::mem_threadgroup);
        for (uint s = nthreads / 2; s > 0; s >>= 1) {
            if (tid < s) {
                smem[tid] += smem[tid + s];
            }
            threadgroup_barrier(mem_flags::mem_threadgroup);
        }
        if (tid == 0) {
            out[row] = smem[0];
        }
    """,
)

def row_sum_c(x, tg=512):
    M, N = x.shape
    out = tg_k(
        inputs=[x],
        template=[("N", N)],
        grid=(M * tg, 1, 1),
        threadgroup=(tg, 1, 1),
        output_shapes=[(M,)],
        output_dtypes=[mx.float32],
    )[0]
