    got = row_sum_c(x)
    exp = mx.sum(x, axis=1)
    mx.eval(got, exp)
    err = mx.max(mx.abs(got - exp)).item()
    scale = mx.max(mx.abs(exp)).item() + 1e-6
    print(f"C {shape}: err/scale={err/scale:.2e}")

x = mx.zeros((16, 300), dtype=mx.float32)
got = row_sum_c(x); mx.eval(got)
print("C zeros max:", mx.max(mx.abs(got)).item())

mx.random.seed(1)
x = mx.random.normal((32, 512)).astype(mx.float32); mx.eval(x)
first = row_sum_c(x); mx.eval(first)
stable = all(mx.allclose(first, row_sum_c(x), atol=1e-5).item() for _ in range(5))
print("C stable:", stable)

# benchmark
big = mx.random.normal((2048, 8192)).astype(mx.float32); mx.eval(big)
for name, fn in [("C tg512", lambda z: row_sum_c(z, 512))]:
    fn(big); mx.eval(big)
    t0 = time.perf_counter()
    for _ in range(20):
        o = fn(big)
    mx.eval(o)
    print(f"{name}: {(time.perf_counter()-t0)/20*1000:.2f} ms")
